class Solution {
  public int maximizeSweetness(int[] sweetness, int k) {
    int lo = 1, hi = 0;
    for (int s : sweetness) hi += s;
    hi /= k + 1;
    // largest minimum piece that still allows k + 1 pieces
    while (lo < hi) {
      int mid = lo + (hi - lo + 1) / 2, pieces = 0, cur = 0;
      for (int s : sweetness) {
        cur += s;
        if (cur >= mid) {
          pieces++;
          cur = 0;
        }
      }
      if (pieces >= k + 1) lo = mid;
      else hi = mid - 1;
    }
    return lo;
  }
}
